import '../../../../../../Core/Models/product_model.dart';import '../../../Home/data/models/product_preview_entities.dart';class CategoryDataPreviewEntities extends ProductPreviewEntities {  CategoryDataPreviewEntities({    required super.id,    required super.name,    required super.price,    required super.discountPrice,    required super.image,  });  factory CategoryDataPreviewEntities.fromProduct(ProductModel product) {    return CategoryDataPreviewEntities(      id: product.id,      image: product.primaryImage?.imageUrl ?? "",      name: product.name,      price: product.price,      discountPrice: product.discountPrice,    );  }  @override  Map<String, dynamic> toMap() {    return {      'id': id,      'name': name,      'price': price,      'discountPrice': discountPrice,      'image_url': primaryImage?.imageUrl ?? '',    };  }}